function renderMechanism(l,root){
 if(l.text)root.append(el('pre','transcript',l.text));
 if(l.kind==='painting'){
 const frame=artStudy('assets/room-study.jpg','A furnished bedroom: doors on both sides, a green window at the back, chairs, wall pictures, and a bed.');const spot=button('',()=>{receipt.textContent='RECEIPT II / 3 · 1 · 4 · 2';receipt.classList.add('found')},'art-window');spot.setAttribute('aria-label','Inspect the back window');const receipt=el('p','discovery','');frame.append(spot);root.prepend(frame);root.append(receipt,el('small','museum-tag','COLLECTION / CHICAGO · STUDY II'));}
 if(l.kind==='url'){const a=el('a','dispatch-link','Dispatch record ↗');a.href=route();a.onclick=e=>{e.preventDefault();syncRoute();$('feedback').textContent='The dispatch address is current.'};root.append(a)}
 if(l.kind==='shapes'){const field=el('div','perimeter');field.append(el('span','dead-centre','∅'));[['△','16 1','top-left'],['□','12 9','bottom-right'],['⬟','13 16','bottom-left'],['⬡','19 5 19 20','top-right']].forEach(([glyph,code,position],i)=>{let b=button(glyph,()=>{b.textContent=code;b.setAttribute('aria-label',glyph+': '+code);b.classList.add('revealed')},'peripheral '+position);b.setAttribute('aria-label','Inspect '+['triangle','square','pentagon','hexagon'][i]);field.append(b)});root.append(field)}
 if(l.kind==='carbon'){const p=el('p','carbon-copy','EVITAGEN');p.tabIndex=0;p.setAttribute('aria-label','Carbon strip. Select its text, or press and hold to lift the carbon.');const reveal=()=>p.classList.add('lifting'),hide=()=>p.classList.remove('lifting');p.onpointerdown=e=>{p.setPointerCapture(e.pointerId);reveal()};p.onpointerup=hide;p.onpointercancel=hide;p.onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();reveal()}};p.onkeyup=hide;p.onblur=hide;root.append(el('p','small-note','CARBON COPY / HOLD TO LIFT'),p)}
 if(l.kind==='audio'){const audio=el('audio');audio.src='assets/dinner.wav';audio.controls=true;audio.preload='metadata';root.append(audio);const details=el('details','signal-record');details.append(el('summary',null,'Non-audio signal record'),el('pre','transcript',baconRecord));root.append(details)}
 if(l.kind==='braille'){const wrap=el('div','braille-plates');const patterns=['1236','15','14','2345','135','1235'];const positions=[[0,0],[0,1],[0,2],[1,0],[1,1],[1,2]];patterns.forEach((pat,j)=>{const plate=el('div','braille-plate');plate.setAttribute('role','img');let occupied=[];positions.forEach(([x,y],i)=>{const active=pat.includes(String(7-(i+1)));const dot=el('span','star '+(active?'lit':''));dot.style.gridColumn=x+1;dot.style.gridRow=y+1;plate.append(dot);if(active)occupied.push(`${x?'right':'left'} ${['top','middle','bottom'][y]}`)});plate.setAttribute('aria-label',`Plate ${j+1}; occupied dots: ${occupied.join(', ')}`);wrap.append(plate)});root.append(wrap)}
 if(l.kind==='music'){const pitches=[['A4',3,4],['D5',6,1],['E5',7,6],['C5',5,3],['E5',7,2],['D5',6,5]];const ns='http://www.w3.org/2000/svg';const score=document.createElementNS(ns,'svg');score.setAttribute('viewBox','0 0 600 180');score.classList.add('score');score.setAttribute('role','img');score.setAttribute('aria-label','Treble clef. Six bars in display order: A4 with four beats of silence; D5 with one; E5 with six; C5 with three; E5 with two; D5 with five.');let markup='<text x="5" y="105" font-size="64">𝄞</text>';for(let y=40;y<=120;y+=20)markup+=`<line x1="5" y1="${y}" x2="595" y2="${y}"/>`;pitches.forEach(([,step,rest],j)=>{let x=70+j*92,y=120-step*10;markup+=`<line x1="${x+44}" y1="40" x2="${x+44}" y2="120"/><ellipse cx="${x}" cy="${y}" rx="8" ry="5"/><line x1="${x+7}" y1="${y}" x2="${x+7}" y2="${y-32}"/><text x="${x-25}" y="160" font-size="13">silence ${rest}</text>`});score.innerHTML=markup;root.append(score)}
 if(l.kind==='knight'){const board=el('div','chessboard');const cells={1:'O',18:'B',35:'S',29:'I',39:'D',54:'I',37:'A',47:'N'};for(let r=7;r>=0;r--)for(let c=0;c<8;c++){const n=r*8+c,s=el('div','chess-square '+((r+c)%2?'dark':''),cells[n]||'');if(n===1)s.classList.add('start');s.setAttribute('aria-label',String.fromCharCode(97+c)+(r+1)+': '+(cells[n]||'empty'));s.append(el('small',null,String.fromCharCode(97+c)+(r+1)));board.append(s)}root.append(board)}
 if(l.kind==='books'){const shelf=el('div','book-shelf');[['Copper','T'],['Ash','A'],['Amber','L'],['Brine','V'],['Dusk','U']].forEach(([name,letter])=>{const b=el('div','book');b.append(el('span',null,name),el('b',null,letter));shelf.append(b)});root.prepend(shelf)}
 if(l.kind==='seurat'){const frame=artStudy('assets/sunday-study.jpg','A riverside park with boats, parasols, people and animals; a large woman stands in the right foreground.');const zoom=el('input');zoom.type='range';zoom.min='1';zoom.max='3';zoom.step='.1';zoom.value='1';zoom.id='artZoom';zoom.setAttribute('aria-label','Artwork magnification');zoom.oninput=()=>{frame.firstChild.style.width=(Number(zoom.value)*100)+'%';frame.classList.toggle('zoomed',zoom.value!=='1')};root.append(frame,el('label','small-note','MAGNIFICATION / SCROLL THE FRAME TO EXPLORE'),zoom)}
 if(l.kind==='source')root.append(document.createComment('Compositor only: the omitted entry is in archive/ledger.txt. Relative to this document, not this fragment.'));
 if(l.kind==='nonogram'){const runs=[1,3,5,7,5,3,1],wrap=el('div','nonogram-wrap'),grid=el('div','nonogram');grid.append(el('span'));runs.forEach(n=>grid.append(el('span','run-clue',n)));runs.forEach((n,r)=>{grid.append(el('span','run-clue',n));for(let c=0;c<7;c++){let b=button('',()=>{b.classList.toggle('filled');b.setAttribute('aria-pressed',String(b.classList.contains('filled')))},'nono-cell');b.setAttribute('aria-label',`Row ${r+1}, column ${c+1}`);b.setAttribute('aria-pressed','false');grid.append(b)}});wrap.append(grid);root.append(wrap)}
 if(l.kind==='grille'){let turn=0;const holes=[[0,0],[0,1],[0,2],[1,1]],grid=el('div','grille'),label=el('p','small-note','POSITION 0° / CORNER ▰');const draw=()=>{grid.replaceChildren();let h=holes.map(p=>{let [r,c]=p;for(let n=0;n<turn;n++)[r,c]=[c,3-r];return r*4+c});grilleLetters.forEach((letter,i)=>grid.append(el('div',h.includes(i)?'hole':'masked',h.includes(i)?letter:'·')));label.textContent='POSITION '+turn*90+'° / CORNER ▰'};draw();root.append(grid,label,button('Rotate stencil ↻',()=>{turn=(turn+1)%4;draw()}))}
 if(l.kind==='clocks')root.append(table(['MARK','LOCAL RECORD','OFFSET'],[['O','22 SEP 00:25','UTC +09:00'],['H','21 SEP 17:40','UTC +01:00'],['E','21 SEP 20:40','UTC +05:30'],['C','21 SEP 11:35','UTC −04:00'],['P','21 SEP 15:20','UTC +00:00']]));
 if(l.kind==='circuit'){let bits=Array(6).fill(0);const masks=[[0,1],[1,2],[2,3],[3,4],[4,5],[0,2,4]],want=[1,1,0,1,1,0];const switches=el('div','switches'),lamps=el('div','lamps'),out=el('p','discovery');const draw=()=>{lamps.replaceChildren();let ok=true;masks.forEach((mask,i)=>{let value=mask.reduce((a,j)=>a^bits[j],0),pass=value===want[i];ok&&=pass;lamps.append(el('p','lamp '+(pass?'on':''),`${mask.map(j=>'ABCDEF'[j]).join(' ⊕ ')} = ${want[i]}  ${pass?'●':'○'}`))});out.textContent=ok?'PANEL / HALO':''};bits.forEach((_,i)=>{let b=button('ABCDEF'[i]+' / 0',()=>{bits[i]^=1;b.textContent='ABCDEF'[i]+' / '+bits[i];b.setAttribute('aria-pressed',String(!!bits[i]));draw()});b.setAttribute('aria-label','Switch '+'ABCDEF'[i]);b.setAttribute('aria-pressed','false');switches.append(b)});draw();root.append(switches,lamps,out)}
 if(l.kind==='cube'){const net=el('div','cube-net');[[0,1,'19 5 1 13'],[1,0,'4 21 19 20'],[1,1,'6 15 12 4'],[1,2,'5 3 8 15'],[2,1,'★'],[3,1,'22 15 9 4']].forEach(([r,c,t])=>{const face=el('div','cube-face',t);face.style.gridRow=r+1;face.style.gridColumn=c+1;net.append(face)});root.append(net)}
 if(l.kind==='parity')root.append(table(['A','B','C','XOR PARITY'],parityRows.map(r=>[r[0],'??',r[1],r[2]])));
}
